"""Explain IO, freezer, command and exclusive wait variants."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1477': ('택배를 기다리는 표지판을 붙인다고 택배 주문이 저절로 생기지는 않습니다. 입출력을 기다리는 방식과 실제 입출력 요청을 만드는 일도 구별해야 합니다.', 'io_wait_event가 대기 명령을 선택하는 역할임을 배웁니다.', '일반: 조건 확인 → schedule, I/O: 조건 확인 → io_schedule을 나란히 쓰세요. 어느 쪽도 이 매크로만으로 특정 디스크 요청을 만드는 것은 아니라고 적으세요.', ['I/O는 입력과 출력을 뜻합니다. 디스크나 장치와 자료를 주고받는 작업 등이 여기에 속합니다. io_wait_event는 I/O 관련 기다림을 표현할 때 사용하는 대기 매크로입니다.', '바깥 모양은 일반 wait_event처럼 do-while 문장입니다. might_sleep로 잠들 수 있는 문맥인지 점검하고 조건이 이미 참이면 내부 대기를 건너뜁니다. 반환 숫자를 대입받는 일반 계산식은 아닙니다.', '조건이 거짓이면 공통 대기에 TASK_UNINTERRUPTIBLE, 비 exclusive 표시, 초기 결과 0을 전달합니다. 실제 대기 명령 자리에는 schedule 대신 io_schedule을 넣습니다. 같은 반복 구조에서 기다리는 명령을 골라 쓰는 것입니다.', 'io_schedule은 I/O 대기와 관련된 처리와 함께 실행을 양보하는 별도 함수입니다. 이 wrapper에 timeout 인자나 신호 오류 반환이 새로 추가되는 것은 아닙니다. 기다림의 종류와 반환 약속을 따로 살펴야 합니다.', '조건은 호출자가 제공한 C 식입니다. 이름에 io가 있다고 자동으로 어느 디스크의 완료 상태를 찾아 읽지는 않습니다. 이 매크로는 디스크 번호나 새 요청의 내용 같은 인자도 받지 않습니다.', '호출자는 실제 요청과 조건 변경, 그 뒤의 깨우기를 올바르게 연결합니다. io_schedule의 후속 구현이 I/O 처리와 연동될 수 있어도, 이 매크로 호출마다 특정 장치 요청을 새로 만든다는 뜻은 아닙니다. 대기 조건은 깨어난 뒤에도 다시 검사합니다.'], [('일반 wait_event와 비교해 대기 명령 자리에서 달라지는 것은?', ['memcpy 대신 read를 써요', 'schedule 대신 io_schedule을 써요'], '공통 매크로에 넘기는 대기 명령이 io_schedule입니다. 자료 복사나 파일 읽기 명령을 직접 교체하는 매크로가 아닙니다.'), ('io_wait_event가 호출마다 특정 디스크 작업을 직접 만들까요?', ['아니요. 호출자가 제공한 조건을 기다려요', '네. 어떤 조건이든 새 디스크 요청을 만들어요'], '이 wrapper는 조건과 대기열을 받아 대기 흐름을 구성합니다. 장치 요청 생성과 조건 대기는 다른 단계이므로 이름만 보고 새 요청을 만든다고 단정하면 안 됩니다.')]), 'os1478': ('학교가 잠시 쉬는 시간에 맞춰 활동을 멈출 수 있는 모둠을 생각해 봅시다. 활동을 잠깐 멈추는 표시가 모둠의 공책을 수정 금지로 만드는 것은 아닙니다.', 'freezable이 태스크의 일시 정지 참여와 관련된 상태임을 배웁니다.', '대기 상태 = INTERRUPTIBLE | FREEZABLE을 적고 두 표시 아래에 “신호 중단”과 “freezer 참여”를 나눠 쓰세요.', ['커널의 freezer는 시스템 절전 같은 과정에서 관련 태스크들을 일시 정지시키는 데 쓰이는 기능입니다. freezable은 이런 일시 정지 처리에 참여할 수 있다는 의미입니다. 메모리를 free한다는 단어와 구별하세요.', '__wait_event_freezable은 TASK_INTERRUPTIBLE과 TASK_FREEZABLE을 |로 합쳐 공통 대기에 전달합니다. 비트 OR인 |는 여러 상태 표시를 함께 켜는 연산입니다. 하나는 신호로 중단 가능한 대기, 다른 하나는 freezer와 관련된 표시입니다.', '바깥 wait_event_freezable은 int 결과를 0으로 준비합니다. 조건이 이미 참이면 바로 0을 돌려줄 수 있습니다. 실제 대기를 거쳐 조건이 맞아도 성공은 0이고 허용되는 신호로 중단되면 공통 경로의 -ERESTARTSYS를 전달합니다.', '이 매크로 안에 시스템 전체를 얼리는 별도 반복문이 있는 것은 아닙니다. 상태 표시를 스케줄러와 freezer의 후속 처리에 연결합니다. 이 줄만 실행했다고 모든 프로세스가 즉시 멈췄다고 해석하면 안 됩니다.', 'timeout 변형은 같은 상태 조합에 남은 시간 계약을 결합합니다. exclusive 변형은 깨우기 한도에 참여하는 등록 표시를 더합니다. freezer 참여, 시간 제한, 깨우기 한도는 서로 다른 선택이므로 이름을 부분별로 읽으세요.', 'freezable이 공유 자료를 불변으로 만들거나 모든 쓰기를 잠그는 것은 아닙니다. 데이터를 함께 쓰는 규약과 조건 변경 뒤의 깨우기는 여전히 필요합니다. 해당 태스크의 freezer 참여 조건과 신호 오류 반환도 호출자가 확인해야 합니다.'], [('freezable 대기가 함께 전달하는 두 상태 표시는?', ['TASK_RUNNING만 전달해요', 'TASK_INTERRUPTIBLE과 TASK_FREEZABLE이에요'], '공통 매크로의 state 인자는 두 표시를 OR로 합친 값입니다. 실행 상태 하나만 주는 것이 아니라 신호 중단과 freezer 참여를 연결합니다.'), ('freezable이면 공유 자료가 자동으로 수정 불가능해질까요?', ['아니요. 태스크 대기의 freezer 참여에 관한 표시예요', '네. 객체에 대한 모든 쓰기가 금지돼요'], '이 wrapper가 선택하는 것은 태스크의 대기 상태입니다. 공유 데이터 잠금이나 메모리 쓰기 보호를 자동으로 제공하는 기능은 아닙니다.')]), 'os1479': ('쉬기 직전에 문을 열고 돌아오면 문을 닫는 규칙이 있습니다. 처음부터 쉴 필요가 없으면 이 두 동작을 하지 않고, 여러 번 쉬면 매번 반복합니다.', 'cmd1·schedule·cmd2의 실행 횟수와 생략 조건을 이해합니다.', '조건 처음 참 → 명령 0번. 내부에서 거짓 두 번 뒤 참 → cmd1,schedule,cmd2를 두 묶음 적으세요.', ['wait_event_cmd는 기다리는 구간의 앞뒤에 호출자가 정한 코드를 넣는 매크로입니다. cmd1과 cmd2는 명령 코드 자리입니다. 프로그램 전체의 시작과 끝에 무조건 한 번씩 실행하는 장치가 아닙니다.', '바깥 조건이 처음부터 참이면 break로 끝나 내부 공통 대기를 부르지 않습니다. 따라서 cmd1도 cmd2도 한 번도 실행되지 않을 수 있습니다. 필요한 자원 해제를 cmd2에만 넣고 항상 실행된다고 믿으면 위험합니다.', '실제 반복에서 조건이 아직 거짓이면 cmd1; schedule(); cmd2 순서로 실행합니다. 앞 명령을 실행하고 CPU를 양보한 뒤 다시 돌아오면 뒤 명령을 실행합니다. 순서가 정해져 있지만 얼마나 오래 기다릴지는 별개입니다.', '깨어나 조건을 다시 봐도 거짓이면 같은 묶음을 또 실행합니다. 예를 들어 내부 조건 검사 결과가 거짓·거짓·참이면 각 명령은 두 번입니다. 카운터를 올리거나 무언가를 소비하는 부작용도 그만큼 반복될 수 있습니다.', '조건이 처음에는 거짓이었어도 등록 후 재검사에서 바로 참이 되면 대기 명령 묶음을 건너뛸 수 있습니다. 즉 바깥 조건이 거짓이었다는 사실만으로 cmd1·cmd2가 적어도 한 번 실행됐다고 단정할 수 없습니다.', '잠금 해제와 재획득을 명령으로 넣는다면 실제 대기마다 올바르게 짝이 맞고 조건 검사의 보호도 유지되는지 확인해야 합니다. exclusive_cmd는 같은 명령 순서에 exclusive 등록을 더합니다. 명령을 항상 실행하는 정리 구문으로 바뀌는 것은 아닙니다.'], [('처음 조건이 참이어도 cmd1과 cmd2는 반드시 실행할까요?', ['네. 입장과 퇴장 때 한 번씩 무조건 해요', '아니요. 내부 대기를 건너뛰면 둘 다 생략돼요'], '바깥 if의 break가 내부 호출보다 앞입니다. 명령은 실제 대기 반복의 cmd에 들어 있으므로 처음부터 조건이 맞으면 실행되지 않습니다.'), ('반복해서 기다리면 두 명령도 여러 번 실행될까요?', ['네. 각 schedule 앞뒤에서 반복될 수 있어요', '아니요. 자동으로 처음 한 번만 실행해요'], '공통 반복은 조건이 거짓일 때마다 cmd1,schedule,cmd2를 실행합니다. 따라서 부작용과 잠금 짝을 반복 가능성까지 고려해 작성해야 합니다.')]), 'os1480': ('한 번에 부를 사람 수를 제한하는 표시는 책 한 권의 주인을 정하는 열쇠가 아닙니다. 부름을 받은 뒤에도 책이 남았는지와 누가 가져갈지를 규칙에 맞춰 확인해야 합니다.', 'exclusive 등록과 조건 성공 코드, 실제 자원 보호를 구별합니다.', 'interruptible_exclusive: 상태 INTERRUPTIBLE·등록 1·초기 결과 0을 쓰세요. 등록 인자 1과 성공 결과 0을 다른 칸에 적으세요.', ['exclusive 변형은 공통 대기의 exclusive 인자에 1을 전달합니다. 공통 매크로는 그 값으로 WQ_FLAG_EXCLUSIVE 등록 표시를 선택합니다. 이 1은 초기 성공 반환값을 1로 바꾸라는 뜻이 아닙니다.', 'interruptible_exclusive는 TASK_INTERRUPTIBLE, killable_exclusive는 TASK_KILLABLE을 사용합니다. killable은 신호 중에서도 치명적인 종료 신호에 반응하는 대기 규칙과 연결됩니다. 어떤 상태든 모든 신호에 똑같이 중단되는 것은 아닙니다.', 'freezable_exclusive는 TASK_INTERRUPTIBLE과 TASK_FREEZABLE을 합친 상태를 사용합니다. 일시 정지 처리 참여와 깨우기 한도 참여를 함께 선택하지만, 두 기능의 의미는 별개입니다.', '여기서 다루는 timeout 없는 반환형 변형들은 초기 결과 0을 사용합니다. 조건이 맞으면 0, 상태가 허용한 신호로 중단되면 -ERESTARTSYS입니다. EXCLUSIVE라는 표시 숫자를 성공 결과로 반환하는 방식이 아닙니다.', '깨우기 순회는 exclusive 표시와 콜백 결과에 따라 한도를 소비합니다. 이것은 누구에게 다시 실행할 기회를 줄지와 관련됩니다. 동시에 여러 태스크가 절대 실행되지 않는다는 mutex 보장이나 자원 소유권 전달은 아닙니다.', '예를 들어 책 한 권이 남았다고 깨웠어도 실제 가져갈 때는 공유 상태를 보호하는 규약으로 남은 수를 확인하고 소비해야 합니다. 단순 예시에서 별도 잠금 없이 두 작업이 각각 1을 보고 가져가면 중복 소비가 생길 수 있습니다. 조건 검사·소비의 보호는 상위 코드가 설계해야 합니다.'], [('exclusive 변형이면 timeout 없는 조건 성공이 반드시 양수일까요?', ['네. EXCLUSIVE 표시값을 반환해요', '아니요. 여기의 조건 성공은 0이에요'], 'exclusive 인자 1과 초기 결과 0은 공통 매크로의 서로 다른 인자입니다. 등록 표시를 고르는 숫자가 성공 반환값으로 바뀌지 않습니다.'), ('exclusive 깨우기로 선택됐으면 공유 자원도 자동으로 독점할까요?', ['아니요. 실제 조건과 자원 소비는 별도 보호 규약이 필요해요', '네. 깨어나는 순간 데이터 mutex를 소유해요'], '깨우기 한도는 데이터 잠금 획득과 다릅니다. 실행을 재개한 뒤 조건과 자원을 올바르게 확인·소비해야 하므로 자동 독점이라는 답은 틀립니다.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_365.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
